const d = $('Dados').first().json;
// normaliza cabeçalhos: minúsculo e sem espaço/underscore (aceita calendarId, calendarid, etc.)
const norm = (r) => { const o = {}; for (const k of Object.keys(r || {})) o[k.toLowerCase().replace(/[\s_]/g, '')] = r[k]; return o; };
const rows = (n) => { try { return $(n).all().map(i => norm(i.json)).filter(r => Object.keys(r).length); } catch (e) { return []; } };
const nao = (v) => String(v ?? 'sim').trim().toLowerCase().startsWith('n');
const bar = rows('Ler barbearia')[0];
if (!bar || nao(bar.ativa ?? bar.ativo)) return [];            // instância não cadastrada ou desativada
if (!bar.evolutionurl || !bar.apikey) return [];                 // sem URL/apikey na planilha
const barbeiros = rows('Ler barbeiros')
  .filter(b => (b.calendarid) && !nao(b.ativa ?? b.ativo))
  .map((b, i) => ({ n: i + 1, nome: b.barbeiro || b.nome, calendarId: String(b.calendarid).trim() }));
const admins = rows('Ler admins').map(a => String(a.telefone || '').replace(/\D/g, '')).filter(Boolean);
const row = norm($('Buscar cliente').first()?.json || {});
const existe = row.telefone !== undefined && row.telefone !== '';
let statusBase = existe ? String(row.status || 'ativo').trim().toLowerCase() : 'novo';
if (!['ativo', 'aguardando_nome', 'novo'].includes(statusBase)) statusBase = 'ativo';
return [{ json: {
  tipo: d.tipo, statusBase, isAdmin: admins.includes(d.telefone), nomeCliente: row.nome || '',
  instancia: d.instancia, telefone: d.telefone,
  evolutionUrl: String(bar.evolutionurl).trim().replace(/\/+$/, ''), apikey: String(bar.apikey).trim(),
  barbeariaNome: bar.nome, horarios: bar.horarios || '', servicos: bar.servicos || '',
  barbeiros, barbeirosTexto: barbeiros.map(b => `${b.n}) ${b.nome}`).join(', '), adminPhones: admins } }];

const ctx = $('Contexto').first().json;
const msg = $('Mensagem').first().json.mensagem || '';
let status = ctx.statusBase;
if (ctx.isAdmin) status = 'admin';
if (!msg) status = 'vazio';
const saudacao = /^(oi+|ol[aá]|opa|e a[ií]|bom dia|boa tarde|boa noite|menu|ajuda)[!. ]*$/i.test(msg);
return [{ json: { ...ctx, status, saudacao, mensagem: msg } }];

let m = $('Mensagem').first().json.mensagem || '';
m = m.replace(/^(meu nome (é|e)|me chamo|pode me chamar de|aqui (é|e) (o |a )?|sou (o |a )?)\s*/i, '')
     .replace(/[^\p{L}\s'-]/gu, '').trim().split(/\s+/).slice(0, 3).join(' ');
let nome = m.split(' ').filter(Boolean).map(p => p.charAt(0).toUpperCase() + p.slice(1).toLowerCase()).join(' ');
if (!nome) nome = 'Cliente';
return [{ json: { nome } }];

const ctx = $('Contexto').first().json;
const tel = ctx.telefone;
const steps = $input.first().json.intermediateSteps || [];
const parse = (v) => { if (typeof v === 'string') { try { return JSON.parse(v); } catch (e) { return v; } } return v; };
const fmt = (iso) => {
  if (!iso) return '?';
  const d = DateTime.fromISO(iso, { zone: 'America/Sao_Paulo' }).setLocale('pt-BR');
  return d.isValid ? d.toFormat("ccc dd/LL 'às' HH:mm") : iso;
};
const falhou = (obs) => /error|erro|exception|failed/i.test(typeof obs === 'string' ? obs : JSON.stringify(obs ?? ''));
const eventos = {};
const coletar = (o) => {
  if (!o || typeof o !== 'object') return;
  if (Array.isArray(o)) { o.forEach(x => coletar(x)); return; }
  if (o.id && (o.summary || o.start)) eventos[o.id] = o;
  Object.values(o).forEach(x => coletar(x));
};
steps.filter(s => s.action?.tool === 'buscar_agendamento_cliente').forEach(s => coletar(parse(s.observation)));
const nomeBarbeiro = (n) => (ctx.barbeiros.find(b => b.n === Number(n)) || {}).nome || '?';
const msgs = [];
for (const s of steps) {
  const tool = s.action?.tool;
  const input = parse(s.action?.toolInput) || {};
  if (falhou(s.observation)) continue;
  const ev = eventos[input.event_id] || {};
  const titulo = ev.summary || ('ID ' + (input.event_id || '?'));
  const antes = fmt(ev.start?.dateTime || ev.start);
  const barb = nomeBarbeiro(input.barbeiro_num);
  if (tool === 'criar_agendamento') {
    msgs.push(`🆕 *Novo agendamento*\n👤 ${input.nome || '?'}\n✂️ ${input.servico || '?'}\n💈 ${barb}\n🕒 ${fmt(input.inicio)}\n📱 ${tel}`);
  } else if (tool === 'cancelar_agendamento') {
    msgs.push(`❌ *Agendamento cancelado*\n📋 ${titulo}\n🕒 ${antes}\n📱 ${tel}`);
  } else if (tool === 'remarcar_agendamento') {
    msgs.push(`🔁 *Agendamento remarcado*\n📋 ${titulo}\n🕒 De ${antes} para ${fmt(input.inicio)}\n📱 ${tel}`);
  }
}
const out = [];
for (const texto of msgs) for (const numero of ctx.adminPhones)
  out.push({ json: { numero, instancia: ctx.instancia, evolutionUrl: ctx.evolutionUrl, apikey: ctx.apikey, texto } });
return out;

const norm = (r) => { const o = {}; for (const k of Object.keys(r || {})) o[k.toLowerCase().replace(/[\s_]/g, '')] = r[k]; return o; };
const barbearias = $('Ler barbearias (lembretes)').all().map(i => norm(i.json));
const from = DateTime.now().plus({ hours: 2 });
const to = DateTime.now().plus({ hours: 3 });
const out = [];
for (const it of $input.all()) {
  const ev = it.json;
  const s = ev.start?.dateTime;
  if (!s) continue;
  const st = DateTime.fromISO(s);
  if (st < from || st >= to) continue;
  const desc = ev.description || '';
  const tel = desc.match(/Tel:\s*(\d{10,15})/);
  const inst = desc.match(/Inst:\s*(\S+)/);
  if (!tel || !inst) continue;
  const bar = barbearias.find(b => String(b.instancia).trim().toLowerCase() === inst[1].toLowerCase());
  if (!bar || !bar.evolutionurl || !bar.apikey) continue;
  const partes = (ev.summary || '').split(' - ');
  const nome = partes[0] || 'cliente';
  const barbeiro = partes[2] ? ` com ${partes[2]}` : '';
  const hora = st.setZone('America/Sao_Paulo').toFormat('HH:mm');
  out.push({ json: { numero: tel[1], instancia: inst[1],
    evolutionUrl: String(bar.evolutionurl).trim().replace(/\/+$/, ''), apikey: String(bar.apikey).trim(),
    texto: `Oi, ${nome}! 💈 Lembrete: seu horário na ${bar.nome || 'barbearia'}${barbeiro} é hoje às ${hora}. Se não puder vir, é só avisar por aqui.` } });
}
return out;
